def stock(i,name,label,url,rows,notes,stype='OTHER',itype='STOCK_SOLUTION'):
 ident='kgmicrobe.ingredient:'+name.lower()
 after={'identifier':ident,'preferred_term':label,'mapping_status':'MAPPED','ingredient_type':itype,'ontology_mapping':{'ontology_id':ident,'ontology_label':label,'ontology_source':'kgmicrobe.ingredient','mapping_quality':'FALLBACK_REGISTRY','evidence':[{'evidence_type':'MANUAL_CURATION','source':url,'notes':'Source-qualified nominal preparation identity under MAPPING_SEMANTICS section3. No exact ontology equivalence to an individual chemical or an unqualified generic stock is asserted.'}]},'notes':notes+' Raw assigned source label: '+CASES[i]['raw_source_label']+'. Quantities in notes preserve source preparation and are not final-medium concentrations. No global synonym is added for this context-dependent label.'}
 if itype=='STOCK_SOLUTION':after['solution_type']=stype
 if rows:
  after['components']=[{'component_name':n,'reference_scope':'UNMAPPED',**({'concentration_value':v,'concentration_unit':u} if v is not None else {})} for n,v,u in rows]
  after['component_assertion']={'method':'RECIPE_TRANSCRIPTION','completeness':('COMPLETE' if i in [4,24,26,27,35] else 'UNKNOWN'),'evidence':[{'evidence_type':'RECIPE_SOURCE','source':url,'source_record':label,'notes':notes}],'notes':('Complete named source-batch input list at this decomposition level; UNMAPPED references do not imply omitted ingredients. Nested stock composition and chemical ambiguities remain separate.' if i in [4,24,26,27,35] else 'Source does not establish complete preparation composition; unreported solvent or pH-adjustment constituents remain unknown. No exhaustive list is claimed.')}
 history(after,'SOURCE_QUALIFIED_PREPARATION_PROPOSED','Propose exact source-qualified nominal ingredient and source partonomy. '+notes)
 proposal([i],name,after,'New source-qualified nominal preparation: '+label,'new_owner',notes)
 return after
